import {
  TableCellType,
  TableDataType,
  TableHeaderType,
  TableRowType,
} from 'components/Table/types';

const TABLE_LABEL_FIELD_IDS = new Set([
  'countries',
  'country',
  'brands',
  'brand',
]);

const isLabelColumn = (key: string, header?: TableHeaderType[]): boolean => {
  if (TABLE_LABEL_FIELD_IDS.has(key)) {
    return true;
  }

  const headerFieldIds = getHeaderFieldIds(header);

  return headerFieldIds.length > 0 && headerFieldIds[0] === key;
};

const getHeaderFieldIds = (header?: TableHeaderType[]): string[] => {
  if (!Array.isArray(header)) {
    return [];
  }

  return header.flatMap((column) => {
    const fieldIds = column.id ? [column.id] : [];

    if (column.children?.length) {
      return [...fieldIds, ...getHeaderFieldIds(column.children)];
    }

    return fieldIds;
  });
};

const isMissingMetricValue = (value: unknown): boolean => {
  if (value === '' || value == null) {
    return true;
  }

  if (value === '-' || value === '–') {
    return true;
  }

  if (typeof value === 'number') {
    return value === 0;
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();

    if (trimmed === '' || trimmed === '-' || trimmed === '–') {
      return true;
    }

    const numeric = Number(trimmed.replace(/[^\d.-]/g, ''));

    return !Number.isNaN(numeric) && numeric === 0;
  }

  return false;
};

const getCellValue = (cell: unknown): unknown => {
  if (cell == null) {
    return null;
  }

  if (typeof cell !== 'object') {
    return cell;
  }

  if ('isEmpty' in cell && (cell as { isEmpty: boolean }).isEmpty) {
    return null;
  }

  const tableCell = cell as TableCellType;

  if ('value' in tableCell) {
    return tableCell.value;
  }

  return null;
};

const hasMeaningfulMetricValue = (cell: unknown): boolean =>
  !isMissingMetricValue(getCellValue(cell));

const isRenderableTableRow = (
  row: TableRowType,
  header?: TableHeaderType[],
): boolean => {
  if (!row || typeof row !== 'object') {
    return false;
  }

  if ('isEmpty' in row && row.isEmpty) {
    return false;
  }

  return Object.entries(row)
    .filter(([key]) => !key.endsWith('_config') && !isLabelColumn(key, header))
    .some(([, cell]) => hasMeaningfulMetricValue(cell));
};

export const hasTableBreakdownData = (tableData?: TableDataType): boolean => {
  if (!tableData || typeof tableData !== 'object') {
    return false;
  }

  if ('empty' in tableData && tableData.empty) {
    return false;
  }

  const { rows, header } = tableData;

  if (!Array.isArray(rows) || rows.length === 0) {
    return false;
  }

  return rows.some(
    (group) =>
      Array.isArray(group) &&
      group.some((row) => isRenderableTableRow(row, header)),
  );
};
